package com.hbm.machine.reactor.icf;
import com.hbm.api.machine.MachineView;
import com.hbm.energy.*;
import com.hbm.multiblock.MuffledMachine;
import java.math.BigInteger;
import java.util.*;
import net.minecraft.core.*;
import net.minecraft.core.particles.DustParticleOptions;
import net.minecraft.nbt.CompoundTag;
import net.minecraft.network.protocol.game.ClientboundBlockEntityDataPacket;
import net.minecraft.server.level.ServerLevel;
import net.minecraft.world.level.Level;
import net.minecraft.world.level.block.entity.BlockEntity;
import net.minecraft.world.level.block.state.BlockState;
import net.minecraft.world.phys.AABB;
/** Source capacitor/emitter/cell adjacency and50-cell laser, using true independent HE port groups. */
public final class IcfLaserEntity extends BlockEntity implements EnergyReceiver,SidedEnergyConnector,MachineView,MuffledMachine{
 private BigInteger power=BigInteger.ZERO;private BigInteger clientCapacity;private boolean muffled;public boolean assembled;public int laserLength,cellCount,emitterCount,capacitorCount,turbochargerCount;private List<BlockPos> ports=List.of();private final Map<BlockPos,PowerNode> nodes=new LinkedHashMap<>();
 public IcfLaserEntity(BlockPos pos,BlockState state){super(IcfReactorContent.LASER_ENTITY.get(),pos,state);}
 public void setup(Set<BlockPos> ports,Set<BlockPos> cells,Set<BlockPos> emitters,Set<BlockPos> capacitors,Set<BlockPos> turbos){disconnect();cellCount=emitterCount=capacitorCount=turbochargerCount=0;var backwards=Direction.from3DDataValue(getBlockState().getValue(IcfStructBlock.META)).getOpposite();var validCells=new HashSet<BlockPos>();var validEmitters=new HashSet<BlockPos>();var validCapacitors=new HashSet<BlockPos>();for(int i=1;i<=cells.size();i++){var at=worldPosition.relative(backwards,i);if(!cells.contains(at))break;cellCount++;validCells.add(at);}for(var emitter:emitters)for(var dir:Direction.values())if(validCells.contains(emitter.relative(dir))){emitterCount++;validEmitters.add(emitter);break;}for(var capacitor:capacitors)for(var dir:Direction.values())if(validEmitters.contains(capacitor.relative(dir))){capacitorCount++;validCapacitors.add(capacitor);break;}for(var turbo:turbos)for(var dir:Direction.values())if(validCapacitors.contains(turbo.relative(dir))){turbochargerCount++;break;}this.ports=ports.stream().map(BlockPos::immutable).toList();}
 public static void tick(Level level,BlockPos pos,BlockState state,IcfLaserEntity laser){if(level instanceof ServerLevel server)laser.serverTick(server);else if(laser.laserLength>0&&level.random.nextInt(5)==0){var dir=Direction.from3DDataValue(state.getValue(IcfStructBlock.META));var rot=dir.getClockWise();double lateral=level.random.nextDouble()*.25-.125,vertical=level.random.nextDouble()*.25-.125;level.addParticle(new DustParticleOptions(new org.joml.Vector3f(1,0,0),1),pos.getX()+.5+dir.getStepX()*.55+rot.getStepX()*lateral,pos.getY()+.5+vertical,pos.getZ()+.5+dir.getStepZ()*.55+rot.getStepZ()*lateral,0,0,0);}}
 private void serverTick(ServerLevel server){var packet=getUpdatePacket();try(var dispatchScope=com.hbm.network.dispatch.PacketDispatch.beginGroup(server.getServer(),packet)){for(var player:server.players())if(player.distanceToSqr(worldPosition.getX(),worldPosition.getY(),worldPosition.getZ())<2500)player.connection.send(packet);dispatchScope.commit();}if(!assembled){disconnect();laserLength=0;return;}updatePorts(server);if(power.signum()<=0){laserLength=0;return;}var dir=Direction.from3DDataValue(getBlockState().getValue(IcfStructBlock.META));for(int i=1;i<50;i++){laserLength=i;var at=worldPosition.offset(dir.getStepX()*i,0,dir.getStepZ()*i);var state=server.getBlockState(at);if(state.is(IcfReactorContent.REACTOR.get())){var core=worldPosition.offset(dir.getStepX()*(i+8),-3,dir.getStepZ()*(i+8));if(server.getBlockEntity(core) instanceof IcfReactorEntity reactor){reactor.laser+=getPower();reactor.maxLaser+=getMaxPower();break;}}if(!state.isAir()){if(state.getBlock().getExplosionResistance()<6000)server.destroyBlock(at,false);break;}}var end=worldPosition.offset(dir.getStepX()*laserLength,dir.getStepY()*laserLength,dir.getStepZ()*laserLength);var box=new AABB(Math.min(worldPosition.getX(),end.getX())+.2,Math.min(worldPosition.getY(),end.getY())+.2,Math.min(worldPosition.getZ(),end.getZ())+.2,Math.max(worldPosition.getX(),end.getX())+.8,Math.max(worldPosition.getY(),end.getY())+.8,Math.max(worldPosition.getZ(),end.getZ())+.8);for(var entity:server.getEntities(null,box)){entity.hurt(server.damageSources().inFire(),50);entity.igniteForSeconds(5);}setPowerExact(BigInteger.ZERO);setChanged();}
 private void updatePorts(ServerLevel server){for(var pos:ports){var node=nodes.get(pos);if(node==null||node.isExpired()){node=new PowerNode(pos);HbmEnergy.nodespace(server).createNode(node);nodes.put(pos,node);}if(node.hasValidNet())node.addReceiver(this);}}
 private void disconnect(){if(level instanceof ServerLevel server)for(var node:nodes.values())HbmEnergy.nodespace(server).destroyNode(node);nodes.clear();}@Override public void setRemoved(){disconnect();super.setRemoved();}@Override public void onChunkUnloaded(){disconnect();super.onChunkUnloaded();}
 @Override public boolean isLoaded(){return !isRemoved()&&level!=null&&level.hasChunkAt(worldPosition);}@Override public boolean canConnect(Direction side){return side!=null;}@Override public long getPower(){return getPowerExact().longValueExact();}@Override public long getMaxPower(){return (long)(Math.sqrt(capacitorCount)*IcfConfig.capacitorPower+Math.sqrt(Math.min(turbochargerCount,capacitorCount))*IcfConfig.turboPower);}@Override public void setPower(long value){setPowerExact(BigInteger.valueOf(value));}@Override public BigInteger getPowerExact(){return power.min(getMaxPowerExact());}@Override public BigInteger getMaxPowerExact(){return level!=null&&level.isClientSide&&clientCapacity!=null?clientCapacity:BigInteger.valueOf(getMaxPower());}@Override public void setPowerExact(BigInteger value){power=value;setChanged();}@Override public long energyStored(){return getPower();}@Override public long energyCapacity(){return getMaxPowerExact().longValueExact();}@Override public boolean isMuffled(){return muffled;}@Override public void setMuffled(boolean value){muffled=value;setChanged();}
 private void save(CompoundTag tag){tag.putLong("power",power.min(BigInteger.valueOf(Long.MAX_VALUE)).longValue());tag.putString("powerExact",power.toString());tag.putBoolean("assembled",assembled);tag.putInt("cellCount",cellCount);tag.putInt("emitterCount",emitterCount);tag.putInt("capacitorCount",capacitorCount);tag.putInt("turbochargerCount",turbochargerCount);tag.putInt("portCount",ports.size());for(int i=0;i<ports.size();i++){var p=ports.get(i);tag.putIntArray("p"+i,new int[]{p.getX(),p.getY(),p.getZ()});}tag.putBoolean("muffled",muffled);}
 private void load(CompoundTag tag){power=tag.contains("powerExact")?new BigInteger(tag.getString("powerExact")):BigInteger.valueOf(tag.getLong("power"));assembled=tag.getBoolean("assembled");cellCount=tag.getInt("cellCount");emitterCount=tag.getInt("emitterCount");capacitorCount=tag.getInt("capacitorCount");turbochargerCount=tag.getInt("turbochargerCount");var ports=new ArrayList<BlockPos>();for(int i=0;i<tag.getInt("portCount");i++){int[] p=tag.getIntArray("p"+i);if(p.length==3)ports.add(new BlockPos(p[0],p[1],p[2]));}this.ports=List.copyOf(ports);muffled=tag.getBoolean("muffled");}
 @Override protected void saveAdditional(CompoundTag tag,HolderLookup.Provider lookup){super.saveAdditional(tag,lookup);save(tag);}@Override protected void loadAdditional(CompoundTag tag,HolderLookup.Provider lookup){super.loadAdditional(tag,lookup);load(tag);}@Override public CompoundTag getUpdateTag(HolderLookup.Provider lookup){var tag=new CompoundTag();tag.putString("powerExact",power.toString());tag.putString("capacityExact",getMaxPowerExact().toString());tag.putInt("capacitorCount",capacitorCount);tag.putInt("turbochargerCount",turbochargerCount);tag.putInt("laserLength",laserLength);tag.putBoolean("muffled",muffled);return tag;}@Override public void handleUpdateTag(CompoundTag tag,HolderLookup.Provider lookup){power=new BigInteger(tag.getString("powerExact"));clientCapacity=new BigInteger(tag.getString("capacityExact"));capacitorCount=tag.getInt("capacitorCount");turbochargerCount=tag.getInt("turbochargerCount");laserLength=tag.getInt("laserLength");muffled=tag.getBoolean("muffled");}@Override public ClientboundBlockEntityDataPacket getUpdatePacket(){return ClientboundBlockEntityDataPacket.create(this);}@Override public void onDataPacket(net.minecraft.network.Connection connection,ClientboundBlockEntityDataPacket packet,HolderLookup.Provider lookup){handleUpdateTag(packet.getTag(),lookup);}
}
